head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10102";
scwin.init_line = 1;
scwin.callLine = 0;
scwin.putLine = 0;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.optionType

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10102.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_optionType", fn: function(){ return ((dma_pageContext.get("optionType") ?? "") === '1' || (dma_pageContext.get("optionType") ?? "") === '3'); } }, { id: "if_optionType_2", fn: function(){ return ((dma_pageContext.get("optionType") ?? "") === '2' || (dma_pageContext.get("optionType") ?? "") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_optionType", fn: function () { return String((dma_pageContext.get("optionType") ?? "")); } },
        { childId: "ipt_callLine", fn: function () { return String((dma_pageContext.get("callLine") ?? "")); } },
        { childId: "ipt_putLine", fn: function () { return String((dma_pageContext.get("putLine") ?? "")); } },
        { childId: "ipt_callExerRsn", fn: function () { return String((dma_pageContext.get("callExerRsn") ?? "")); } },
        { childId: "ipt_putExerRsn", fn: function () { return String((dma_pageContext.get("putExerRsn") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // 콜 또는 콜&풋 선택시
        if( $c.util.getComponent('ipt_optionType').getValue()  === "1" || $c.util.getComponent('ipt_optionType').getValue() === "3" ){
            if( ($c.util.getComponent('ipt_callLine').getValue() === null ? '' : String($c.util.getComponent('ipt_callLine').getValue())) === '' || $c.util.getComponent('ipt_callLine').getValue() === "0" ){
                for(let i = 0 ; i < scwin.init_line ; i++){
                    scwin.callAdd();
                }
            }else{
                scwin.callLine =  ($c.util.getComponent('ipt_callLine').getValue() === null ? '' : String($c.util.getComponent('ipt_callLine').getValue())) === '' ? 0 : Number("" + dma_pageContext.get("callLine") + "");
                scwin.callInit();
            }
        }

        // 풋 또는 콜&풋 선택시
        if( $c.util.getComponent('ipt_optionType').getValue()  === "2" || $c.util.getComponent('ipt_optionType').getValue() === "3" ){
            if( ($c.util.getComponent('ipt_putLine').getValue() === null ? '' : String($c.util.getComponent('ipt_putLine').getValue())) === '' || $c.util.getComponent('ipt_putLine').getValue() === "0"){
                for(let i = 0 ; i < scwin.init_line ; i++){
                    scwin.putAdd();
                }
            }else{
                scwin.putLine =  ($c.util.getComponent('ipt_putLine').getValue() === null ? '' : String($c.util.getComponent('ipt_putLine').getValue())) === '' ? 0 : Number("" + dma_pageContext.get("putLine") + "");
                scwin.putInit();
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10102.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_callAdd_onclick
 * @description btn_callAdd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_callAdd_onclick = function(e){
    try {
        scwin.callAdd()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10102.btn_callAdd_onclick' }); }
};

/**
 * @method
 * @name btn_callDel_onclick
 * @description btn_callDel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_callDel_onclick = function(e){
    try {
        scwin.callDel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10102.btn_callDel_onclick' }); }
};

/**
 * @method
 * @name btn_putAdd_onclick
 * @description btn_putAdd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_putAdd_onclick = function(e){
    try {
