/**
 * @method
 * @name btn_putDel_onclick
 * @description btn_putDel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_putDel_onclick = function(e){
    try {
        scwin.putDel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10102.btn_putDel_onclick' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form('__self.form')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10102.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_sendCancel_onclick
 * @description btn_sendCancel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendCancel_onclick = function(e){
    try {
        scwin.send_cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10102.btn_sendCancel_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal_offMask
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name chkDate
 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name callInit
 * @description call Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.callInit = function () {
    for (let i = 0; i < scwin.callLine; i++) {
        const htm = " <tr class=\"first\" id=\"tr_call_" + (i + 1) + "\">" + "	    <th class=\"first type-00 txc\">" + (i + 1) + "차</th>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"call_exer_strt_dd" + (i + 1) + "\" id=\"call_exer_strt_dd" + (i + 1) + "\" value=\"" + (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#call_exer_strt_dd" + (i + 1)).replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#call_exer_strt_dd" + (i + 1)).replace(/^#/, '')).getValue() : undefined) + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사개시일' )\" onfocus=\"cal_offMask('document.JLDINF10102.call_exer_strt_dd" + (i + 1) + "')\" onkeyup=\"chkDate('document.JLDINF10102.call_exer_strt_dd" + (i + 1) + "')\" /></div></td>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"call_exer_end_dd" + (i + 1) + "\"  id=\"call_exer_end_dd" + (i + 1) + "\" value=\"" + (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#call_exer_end_dd" + (i + 1)).replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#call_exer_end_dd" + (i + 1)).replace(/^#/, '')).getValue() : undefined) + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사종료일' )\" onfocus=\"cal_offMask('document.JLDINF10102.call_exer_end_dd" + (i + 1) + "')\" onkeyup=\"chkDate('document.JLDINF10102.call_exer_end_dd" + (i + 1) + "')\" /></div></td>" + "	</tr></br>";
        $("#tbl_call").append(htm);
        $("#call_exer_strt_dd" + (i + 1)).datepicker(myDateOpts);
        $("#call_exer_end_dd" + (i + 1)).datepicker(myDateOpts);
    }
    if (scwin.callLine < scwin.init_line) {
        for (let i = scwin.callLine; i < scwin.init_line; i++) {
            scwin.callAdd();
        }
    }
};

/**
