 */
scwin.putInit = function () {
    for (let i = 0; i < scwin.putLine; i++) {
        const htm = " <tr class=\"first\" id=\"tr_put_" + (i + 1) + "\">" + "	    <th class=\"first type-00 txc\">" + (i + 1) + "차</th>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"put_exer_strt_dd" + (i + 1) + "\" id=\"put_exer_strt_dd" + (i + 1) + "\" value=\"" + (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#put_exer_strt_dd" + (i + 1)).replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#put_exer_strt_dd" + (i + 1)).replace(/^#/, '')).getValue() : undefined) + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사개시일' )\" onfocus=\"cal_offMask('document.JLDINF10102.put_exer_strt_dd" + (i + 1) + "')\" onkeyup=\"chkDate('document.JLDINF10102.put_exer_strt_dd" + (i + 1) + "')\" /></div></td>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"put_exer_end_dd" + (i + 1) + "\"  id=\"put_exer_end_dd" + (i + 1) + "\" value=\"" + (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#put_exer_end_dd" + (i + 1)).replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("#put_exer_end_dd" + (i + 1)).replace(/^#/, '')).getValue() : undefined) + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사종료일' )\" onfocus=\"cal_offMask('document.JLDINF10102.put_exer_end_dd" + (i + 1) + "')\" onkeyup=\"chkDate('document.JLDINF10102.put_exer_end_dd" + (i + 1) + "')\" /></div></td>" + "	</tr></br>";
        $("#tbl_put").append(htm);
        $("#put_exer_strt_dd" + (i + 1)).datepicker(myDateOpts);
        $("#put_exer_end_dd" + (i + 1)).datepicker(myDateOpts);
    }
    if (scwin.putLine < scwin.init_line) {
        for (let i = scwin.putLine; i < scwin.init_line; i++) {
            scwin.putAdd();
        }
    }
};

/**
 * @method
 * @name callAdd
 * @description call Add 처리
 * @returns {void}
 * @hidden N
 */
scwin.callAdd = function () {
    scwin.callLine++;
    const htm = " <tr class=\"first\" id=\"tr_call_" + scwin.callLine + "\">" + "	    <th class=\"first type-00 txc\">" + scwin.callLine + "차</th>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"call_exer_strt_dd" + scwin.callLine + "\" id=\"call_exer_strt_dd" + scwin.callLine + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사개시일' )\" onfocus=\"cal_offMask('document.JLDINF10102.call_exer_strt_dd" + scwin.callLine + "')\" onkeyup=\"chkDate('document.JLDINF10102.call_exer_strt_dd" + scwin.callLine + "')\" /></div></td>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"call_exer_end_dd" + scwin.callLine + "\"  id=\"call_exer_end_dd" + scwin.callLine + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사종료일' )\" onfocus=\"cal_offMask('document.JLDINF10102.call_exer_end_dd" + scwin.callLine + "')\" onkeyup=\"chkDate('document.JLDINF10102.call_exer_end_dd" + scwin.callLine + "')\" /></div></td>" + " </tr>";
    $("#tbl_call").append(htm);
    $("#call_exer_strt_dd" + scwin.callLine).datepicker(myDateOpts);
    $("#call_exer_end_dd" + scwin.callLine).datepicker(myDateOpts);
};

/**
 * @method
 * @name callDel
 * @description call Del 처리
 * @returns {void}
 * @hidden N
 */
scwin.callDel = function () {
    if (scwin.callLine > 0) {
        $("#tr_call_" + scwin.callLine).remove();
        scwin.callLine--;
    }
};

/**
 * @method
 * @name putAdd
 * @description put Add 처리
 * @returns {void}
 * @hidden N
 */
scwin.putAdd = function () {
    scwin.putLine++;
    const htm = " <tr class=\"first\" id=\"tr_put_" + scwin.putLine + "\">" + "	    <th class=\"first type-00 txc\">" + scwin.putLine + "차</th>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"put_exer_strt_dd" + scwin.putLine + "\" id=\"put_exer_strt_dd" + scwin.putLine + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사개시일' )\" onfocus=\"cal_offMask('document.JLDINF10102.put_exer_strt_dd" + scwin.putLine + "')\" onkeyup=\"chkDate('document.JLDINF10102.put_exer_strt_dd" + scwin.putLine + "')\" /></div></td>" + "		<td class=\"txc\"><div style=\"display:flex; align-items:center;\"><input type=\"text\" name=\"put_exer_end_dd" + scwin.putLine + "\"  id=\"put_exer_end_dd" + scwin.putLine + "\" class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사종료일' )\" onfocus=\"cal_offMask('document.JLDINF10102.put_exer_end_dd" + scwin.putLine + "')\" onkeyup=\"chkDate('document.JLDINF10102.put_exer_end_dd" + scwin.putLine + "')\" /></div></td>" + " </tr>";
    $("#tbl_put").append(htm);
    $("#put_exer_strt_dd" + scwin.putLine).datepicker(myDateOpts);
    $("#put_exer_end_dd" + scwin.putLine).datepicker(myDateOpts);
};

/**
 * @method
 * @name putDel
 * @description put Del 처리
 * @returns {void}
 * @hidden N
 */
scwin.putDel = function () {
    if (scwin.putLine > 0) {
        $("#tr_put_" + scwin.putLine).remove();
        scwin.putLine--;
    }
};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function (fm) {

    for(i=0;i<(((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["callLine"] && (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["callLine"]).getValue ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["callLine"]).getValue() : (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("callLine") || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("callLine").getValue() : ''));i++){
        parent.opener.$("#call_exer_strt_dd" + (i+1)).remove();
